const CONCEPTS={
  memory:{title:"Memory · state across time",copy:"Moves continuity out of a finite prompt into governed working, episodic, semantic and personal stores. The control problem is retrieving the right evidence at the right moment."},
  skills:{title:"Skills · procedural expertise",copy:"Moves repeatable methods out of improvisation into discoverable, versioned procedures with declared dependencies, progressive disclosure and runtime binding."},
  protocols:{title:"Protocols · interaction structure",copy:"Moves tool, agent and user interactions out of free-form prose into validated contracts with lifecycle semantics, permissions and discovery metadata."},
  workspace:{title:"Filesystem / workspace · operational substrate",copy:"Materializes task state, drafts, artifacts and execution checkpoints in a bounded, inspectable environment. It supports working memory and tool execution, but is not a fourth externalization dimension."}
};
function externalization(){const host=document.querySelector('[data-externalization]');if(!host)return;host.innerHTML=`<div class="external-map"><div class="external-harness"><div class="external-harness__title"><b>Enterprise agent harness</b><span>the cognitive + operational environment</span></div><div class="external-harness__rails" aria-label="Harness operational surfaces"><span>Permission</span><span>Control</span><span>Observability</span></div></div><svg class="external-lines" viewBox="0 0 1000 560" preserveAspectRatio="none" aria-hidden="true"><line x1="170" y1="180" x2="500" y2="290"/><line x1="830" y1="180" x2="500" y2="290"/><line x1="830" y1="420" x2="500" y2="290"/><line class="external-lines__support" x1="170" y1="420" x2="500" y2="290"/></svg><div class="external-core"><b>Model</b><span>reason + synthesize</span></div>${Object.entries(CONCEPTS).map(([id,c])=>`<button class="external-node" type="button" data-concept="${id}"><b>${c.title.split(' · ')[0]}</b><span>${c.title.split(' · ')[1]}</span></button>`).join('')}</div><div class="external-detail" data-concept-copy aria-live="polite"><b>The harness contains the system</b><span>Memory, skills and protocols are the three externalization dimensions. Permission, control and observability coordinate them; the bounded workspace supports stateful execution.</span></div>`;host.querySelectorAll('[data-concept]').forEach(b=>b.addEventListener('click',()=>{host.querySelectorAll('[data-concept]').forEach(x=>x.classList.toggle('is-active',x===b));const c=CONCEPTS[b.dataset.concept];host.querySelector('[data-concept-copy]').innerHTML=`<b>${c.title}</b><span>${c.copy}</span>`}))}

const APPROACHES={
  opencode:{name:"OpenCode",bet:"Engineering depth",stack:"TypeScript / Bun · MIT · ~157k stars",strengths:["Mature context compaction and output reservation","Tree-sitter bash safety pipeline","Five-tier enterprise configuration","Native skills and typed plugin tools"],tradeoffs:["Narrower provider breadth","No native HITL freeze/resume","Limited built-in evaluation and tracing"],verdict:"Best when a terminal-first team wants the deepest engineering concentrated in one codebase."},
  claw:{name:"Claw-Code",bet:"Hard safety rails",stack:"Rust · license unspecified · ~191k stars",strengths:["Kernel-grade Linux namespace isolation","Hard iteration cap and panic-catching threads","Deferred tool loading","Per-subagent least-privilege allowlists"],tradeoffs:["License clarity blocks adoption","Hardening is partially unmerged","Cost telemetry is a stub","Steeper Rust staffing curve"],verdict:"The strongest safety story, provided licensing and Rust capability are resolved."},
  pi:{name:"Pi",bet:"Minimal core",stack:"TypeScript / Bun · MIT · ~47k stars",strengths:["35+ model providers","20+ lifecycle hooks","Tree-structured forkable sessions","Pluggable execution backends"],tradeoffs:["Multi-agent and MCP are extensions","No core iteration limit","Smaller contributor base","Skill execution is less mature"],verdict:"Best when the organization wants to own and extend the harness itself."},
  deep:{name:"DeepAgents",bet:"Batteries included",stack:"Python / LangGraph · MIT · ~22k stars",strengths:["Native HITL interrupts and resume","Best-in-class progressive skill disclosure","Model-aware profiles","Tracing, evaluation, IDE and remote sandboxes"],tradeoffs:["Limited non-filesystem permission granularity","Shell safety delegated to the backend","No failure-count circuit breaker","Framework version coupling"],verdict:"The strongest all-round fit when operational capabilities must arrive together."}
};
let activeApproach='opencode';
function approaches(){const host=document.querySelector('[data-approaches]');if(!host)return;const render=()=>{const a=APPROACHES[activeApproach];host.innerHTML=`<div class="approach-tabs" role="tablist">${Object.entries(APPROACHES).map(([id,x])=>`<button class="harness-tab" type="button" role="tab" data-approach="${id}" aria-selected="${id===activeApproach}">${x.name}</button>`).join('')}</div><div class="approach-card"><div class="approach-card__identity"><span>${a.bet}</span><h3>${a.name}</h3><span>${a.stack}</span></div><div class="approach-card__body"><div class="approach-columns"><div><b>Strengths</b><ul>${a.strengths.map(x=>`<li>${x}</li>`).join('')}</ul></div><div><b>Trade-offs</b><ul>${a.tradeoffs.map(x=>`<li>${x}</li>`).join('')}</ul></div></div><p class="verdict"><strong>Fit:</strong> ${a.verdict}</p></div></div>`;host.querySelectorAll('[data-approach]').forEach(b=>b.addEventListener('click',()=>{activeApproach=b.dataset.approach;render()}))};render()}

const MATRICES={
  memory:{label:"Memory + context",headers:["Capability","OpenCode","Claw-Code","Pi","DeepAgents"],rows:[["Context compaction / summarization","Yes — most mature","Yes","Yes","Yes — multi-layer"],["Context budget management","Output reservation","Partial","Yes","Yes"],["Persistent storage","SQLite + files","JSONL + rotation","JSONL tree","4 pluggable backends"],["Prompt-cache optimization","Yes","Partial","Yes","Yes"],["Hierarchical project memory","Yes","Partial","Yes","Yes"],["Episodic / cross-session recall","No","No","Partial","Partial"],["HITL freeze / resume","Partial","No","Partial","Yes — native interrupts"]]},
  tools:{label:"Tools + extension",headers:["Capability","OpenCode","Claw-Code","Pi","DeepAgents"],rows:[["Typed / uniform tool interface","Yes","Yes","Yes","Yes"],["Built-in tools (core)","~13","40 (6+34)","7","9"],["Full skills system","Yes","Partial","Yes","Yes"],["Progressive disclosure","Partial","Yes","Partial","Yes — best-in-class"],["MCP support","Yes","Yes","No","Yes"],["Hook / middleware events","5 (plugins)","Pre/Post/Failure","20+","11 middleware layers"],["LLM provider breadth","Limited","Limited","35+","30+"]]},
  agents:{label:"Agents + loop safety",headers:["Capability","OpenCode","Claw-Code","Pi","DeepAgents"],rows:[["Sub-agent / task delegation","Yes","Yes","Partial","Yes"],["Coordinator–worker (least privilege)","Yes","Yes","Partial","Yes"],["Shared multi-agent scratchpad","No","No","No","Yes — native state channel"],["Loop / step limits in core","Yes","Yes — hard cap","No","Yes"],["Hard circuit breakers","No","Yes — panic catching","No","No"]]},
  ops:{label:"Safety + operations",headers:["Capability","OpenCode","Claw-Code","Pi","DeepAgents"],rows:[["Execution sandboxing","Git worktrees","Linux namespaces","Pluggable backends","5 remote backends"],["Bash security pipeline","Yes — tree-sitter","Partial","Yes","Partial — backend-delegated"],["Permission policy","Yes","Yes","Partial","Partial"],["Observability / tracing","Logs + opt-in OTel","Lane events","DIY via hooks","First-class tracing UI"],["Native evaluation framework","No","No","No","Yes"],["IDE protocol integration","No","No","No","Yes"]]}
};
let activeMatrix='memory';
function comparison(){const host=document.querySelector('[data-comparison]');if(!host)return;const render=()=>{const m=MATRICES[activeMatrix];host.innerHTML=`<div class="matrix-tabs" role="tablist">${Object.entries(MATRICES).map(([id,x])=>`<button class="harness-tab" type="button" role="tab" data-matrix="${id}" aria-selected="${id===activeMatrix}">${x.label}</button>`).join('')}</div><div class="matrix-wrap"><table><thead><tr>${m.headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${m.rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;host.querySelectorAll('[data-matrix]').forEach(b=>b.addEventListener('click',()=>{activeMatrix=b.dataset.matrix;render()}))};render()}

const LAYERS=[
  ["01","Identity + context","Establishes the organization, user, agent, data, tools and approval rules for every run."],
  ["02","Managed memory","Separates working, episodic, organizational and personal continuity with provenance."],
  ["03","Governed skills","Discovers and loads versioned procedures only when the task requires them."],
  ["04","Bounded workspace","Provides safe external working memory with separated inputs, outputs and persistent artifacts."],
  ["05","Tools + delegation","Validates interfaces, scopes credentials, controls child agents and makes side effects retry-safe."],
  ["06","Orchestration + policy","Runs the bounded loop, checkpoints pauses and authorizes every consequential action."],
  ["07","Observability + evaluation","Reconstructs runs and turns evidence into tested, staged and reversible improvements."]
];
let blueprintView='layers';
function blueprint(){const host=document.querySelector('[data-blueprint]');if(!host)return;host.innerHTML=`<div class="blueprint-tabs" role="tablist"><button class="harness-tab" role="tab" data-blueprint="layers" aria-selected="${blueprintView==='layers'}">Layer stack</button><button class="harness-tab" role="tab" data-blueprint="loops" aria-selected="${blueprintView==='loops'}">Two-speed loop</button></div><div class="blueprint-shell"><div class="blueprint-head"><h3>${blueprintView==='layers'?'Seven governed layers':'Operate fast. Improve deliberately.'}</h3><p>${blueprintView==='layers'?'Select a layer to inspect its production responsibility.':'Runtime execution and platform improvement move at different speeds and exchange evidence.'}</p></div>${blueprintView==='layers'?`<div class="layer-stack">${LAYERS.map(x=>`<button class="layer-row" type="button" data-layer="${x[0]}"><span>${x[0]}</span><b>${x[1]}</b><small>${x[2]}</small></button>`).join('')}</div><div class="blueprint-detail" data-layer-copy>Select a layer to focus the blueprint.</div>`:`<div class="speed-loops"><div class="speed-loop"><b>Fast operational loop</b><span>Retrieve → load → authorize → act → persist</span></div><div class="loop-bridge">⇄</div><div class="speed-loop"><b>Slow improvement loop</b><span>Aggregate → propose → test → review → release</span></div><div class="loop-steps"><span>Version evidence</span><span>Evaluate outcomes</span><span>Review changes</span><span>Stage release</span><span>Monitor + rollback</span></div></div>`}</div>`;host.querySelectorAll('[data-blueprint]').forEach(b=>b.addEventListener('click',()=>{blueprintView=b.dataset.blueprint;blueprint()}));host.querySelectorAll('[data-layer]').forEach(b=>b.addEventListener('click',()=>{host.querySelectorAll('[data-layer]').forEach(x=>x.classList.toggle('is-active',x===b));const l=LAYERS.find(x=>x[0]===b.dataset.layer);host.querySelector('[data-layer-copy]').innerHTML=`<b>${l[1]}</b><br>${l[2]}`}))}

const RELATIONSHIPS=[["Memory → Skills","Past outcomes reveal where procedures need improvement"],["Skills → Memory","Procedure-driven work produces structured evidence and artifacts"],["Skills → Tools","Instructions connect to executable capabilities"],["Tools → Memory","Results, errors and approvals become durable evidence"],["Policy → Tools","Every action receives consistent authorization treatment"],["Observability → Policy","Incidents and usage patterns expose missing controls"],["Evaluation → Skills","Quality evidence supports tested revisions"]];
function reinforcement(){const host=document.querySelector('[data-reinforcement]');if(!host)return;host.innerHTML=`<div class="reinforcement-map">${RELATIONSHIPS.map((x,i)=>`<button class="reinforcement-node" type="button" data-relation="${i}">${x[0]}</button>`).join('')}</div><div class="reinforcement-copy" data-relation-copy><b>A governed feedback system</b><span>Select a relationship to see what it enables.</span></div>`;host.querySelectorAll('[data-relation]').forEach(b=>b.addEventListener('click',()=>{host.querySelectorAll('[data-relation]').forEach(x=>x.classList.toggle('is-active',x===b));const r=RELATIONSHIPS[Number(b.dataset.relation)];host.querySelector('[data-relation-copy]').innerHTML=`<b>${r[0]}</b><span>${r[1]}.</span>`}))}
function checklist(){const boxes=[...document.querySelectorAll('[data-checklist] input')],count=document.querySelector('[data-check-count]');if(!count)return;const update=()=>{count.textContent=boxes.filter(x=>x.checked).length};boxes.forEach(x=>x.addEventListener('change',update));update()}
function navigation(){const progress=document.querySelector('.article-toc__progress span'),links=[...document.querySelectorAll('.article-toc a')],sections=links.map(x=>document.querySelector(x.getAttribute('href'))).filter(Boolean);const update=()=>{const max=document.documentElement.scrollHeight-innerHeight;if(progress)progress.style.width=`${max>0?scrollY/max*100:0}%`;let current=sections[0];sections.forEach(s=>{if(s.getBoundingClientRect().top<=150)current=s});links.forEach(a=>a.setAttribute('aria-current',String(current&&a.hash===`#${current.id}`)))};addEventListener('scroll',update,{passive:true});update()}
document.addEventListener('DOMContentLoaded',()=>{externalization();approaches();comparison();blueprint();reinforcement();checklist();navigation()});
